sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var item = newValue;
    var quantity = g_form.getValue('quantity') || 1;
    var ga = new GlideAjax('x_1850703_it_equ_0.GetItemPrice');
    ga.addParam('sysparm_name', 'getPrice');
    ga.addParam('item', item);
    ga.getXML(getResponse);

    function getResponse(response) {
        var answer = response.responseXML.documentElement.getAttribute('answer');
        var totalPrice=answer*quantity;
		g_form.setValue('total_price',totalPrice.toString());
    }
}
